function q(string $t,string $a,string $b,string $c,string $d,string $k):array{$o=[$a,$b,$c,$d];return[$t,$o,$k,$o[ord($k)-97]];}function save22(int $n,array $qs):void{$db=db();$l=query_one("SELECT l.id FROM lessons l JOIN grades g ON g.id=l.grade_id JOIN subjects s ON s.id=l.subject_id WHERE g.grade_number=10 AND s.name_en='Buddhism' AND l.medium='Sinhala' AND l.display_order=? AND l.status='active' LIMIT 1",'i',[$n]);if(!$l)throw new RuntimeException("Lesson $n not found");$quiz=query_one("SELECT id FROM quizzes WHERE lesson_id=? AND status='active' ORDER BY id LIMIT 1",'i',[(int)$l['id']]);if(!$quiz)throw new RuntimeException("Lesson $n quiz not found");$id=(int)$quiz['id'];$s=$db->prepare("DELETE qa FROM quiz_answers qa JOIN quiz_questions qq ON qq.id=qa.question_id WHERE qq.quiz_id=? AND qq.activity_type='challenge'");$s->bind_param('i',$id);$s->execute();$s=$db->prepare("DELETE FROM quiz_questions WHERE quiz_id=? AND activity_type='challenge'");$s->bind_param('i',$id);$s->execute();$s=$db->prepare("INSERT INTO quiz_questions(quiz_id,activity_type,question_si,option_a_si,option_b_si,option_c_si,option_d_si,correct_option,explanation_si,display_order,status) VALUES(?,'challenge',?,?,?,?,?,?,?,?,'active')");foreach($qs as $i=>$v){[$t,$o,$k,$e]=$v;$p=$i+1;$s->bind_param('isssssssi',$id,$t,$o[0],$o[1],$o[2],$o[3],$k,$e,$p);if(!$s->execute())throw new RuntimeException($s->error);}$title="$n වන පාඩම — MCQ ප්‍රශ්න 30";$s=$db->prepare("UPDATE quizzes SET title_si=?,timer_minutes=30,pass_mark=50 WHERE id=?");$s->bind_param('si',$title,$id);$s->execute();$c=(int)(query_one("SELECT COUNT(*) n FROM quiz_questions WHERE quiz_id=? AND activity_type='challenge' AND status='active'",'i',[$id])['n']??0);if($c!==30)throw new RuntimeException("Lesson $n has $c MCQs");}
